target.css:
:root {
  --ink: #20233d;
  --paper: #fffdf6;
  --plum: #5b3c8c;
  --coral: #ec6f5b;
  --mint: #b8dfc9;
  --sun: #f5c94e;
  --line: #d9d8cf;
  --muted: #74768a;
}

.print-card {
  box-sizing: border-box;
  width: 480px;
  padding: 16px;
  color: var(--ink);
  background: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 18px;
}

.card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 14px;
}

.kicker {
  margin: 0 0 4px;
  color: var(--plum);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 1.1px;
}

h1 {
  margin: 0;
  font-size: 23px;
  line-height: 1;
  letter-spacing: -0.7px;
}

.status {
  padding: 5px 8px;
  color: var(--paper);
  background: var(--plum);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.7px;
}

.slot-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  overflow: hidden;
  border: 1px solid var(--ink);
  border-radius: 10px;
}

.slot {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 10px 12px;
  background: var(--mint);
}

.slot + .slot {
  border-left: 1px solid var(--ink);
}

.slot span {
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.8px;
}

.slot strong {
  font-size: 15px;
  line-height: 1;
}

.ink-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 13px 2px;
}

.ink-copy {
  margin: 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.4;
}

.ink-copy strong {
  color: var(--ink);
  font-size: 14px;
}

.swatches {
  display: flex;
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.swatches li {
  width: 24px;
  height: 24px;
  border: 2px solid var(--ink);
  border-radius: 50%;
}

.swatches li:nth-child(1) {
  background: var(--plum);
}

.swatches li:nth-child(2) {
  background: var(--coral);
}

.swatches li:nth-child(3) {
  background: var(--sun);
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 12px;
  border-top: 1px solid var(--line);
}

.folio {
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.8px;
}

button {
  padding: 8px 11px;
  color: var(--paper);
  background: var(--coral);
  border: 2px solid var(--coral);
  border-radius: 8px;
  font-size: 12px;
  font-weight: 800;
}

